// Literal port of the team's Casa3DSDK (module vegetation/bridge). Generated by codemod and reviewed; see MIGRATION.md.
import type { Kernel, Shared } from '../kernel-types.js';

export function installVegetationBridge(K: Kernel, shared: Shared): void {
  const seedKey = (id: any): any => K.seedKey(id);
  const { THREE, SEED, rngString } = K;
  // ---------- R39: vegetation from the game-vegetation package (cfg.vegetation): one merged mesh per group (wood, foliage, flowers), wind and bending around the player ----------
  const VEG_POT = ['potted_areca', 'potted_snake_plant', 'potted_fern'], VEG_CACTUS = { cactus_mandacaru: 'mandacaru', cactus_palm: 'prickly_pear', cactus_crown: 'crown_cactus', cactus_xique: 'xique_xique', cactus_pot: 'potted_cactus' };
  const VEG_MAP = {
    tree_small: ['guava_tree', 'lemon_tree', 'pitanga_bush_tree'], tree_large: ['mango_tree', 'oak_like'], fruit_tree: ['mango_tree', 'avocado_tree', 'lemon_tree', 'jabuticaba_tree'], palm_tree: ['coconut_palm'],
    shrub: ['generic_round_shrub'], flowering_shrub: ['hibiscus_shrub', 'azalea', 'croton'], floor_plant_tall: VEG_POT, floor_plant: VEG_POT, outdoor_pot: VEG_POT, toilet: VEG_POT, floor_plant_low: ['potted_succulents', 'potted_cactus'], table_plant: ['potted_succulents', 'potted_cactus'],
    clump: ['lawn_tuft'], banana_plant: ['banana_with_bunch'], ipe_tree: ['yellow_ipe', 'pink_ipe'], climber: ['bougainvillea_vine', 'ivy'], hedge: ['boxwood_hedge', 'ixora_hedge'],
  };
  for (const k of Object.keys(VEG_CACTUS)) VEG_MAP[k] = [VEG_CACTUS[k]];
  const VEG_PLANTER = { planter_bed: ['rose_bush_red', 'rose_bush_pink', 'rose_bush_white', 'marigold', 'periwinkle_pink', 'periwinkle_white', 'daisy'], planter_bed_small: ['rose_bush_red', 'marigold', 'periwinkle_pink', 'daisy'], garden_bed: ['lawn_tuft', 'wild_flowers'] };
  // plan item -> plan positions (returns true if the vegetation took care of the item; false lets the old builder draw)
  function vegItem(m, M, group) {
    const V = shared.ctx.veg; if (!V) return false; const ids = VEG_MAP[m.type], can = VEG_PLANTER[m.type]; if (!ids && !can) return false;
    const rnd = rngString(SEED() + '|' + seedKey(m.id) + '|veg'), pick = l => l[Math.min(l.length - 1, (rnd() * l.length) | 0)], ok = id => { if (V.ok.has(id)) return V.ok.get(id); let r = true; try { V.S.toSpec(id); } catch (e) { r = false; } V.ok.set(id, r); return r; };
    const y = (M.base || 0) + (M.y || 0), key = group + '|' + y.toFixed(3); let G = V.groups.get(key); if (!G) V.groups.set(key, G = { group, y, pl: [] });
    const sd = (rnd() * 1e9) | 0;
    if (can) {
      const ids2 = can.filter(ok); if (!ids2.length) return false; const sw = Math.abs(Math.sin(M.ry || 0)) > 0.7, w = sw ? M.d : M.w, d = sw ? M.w : M.d;
      const lst = V.G.scatter({ rect: { x: M.x - w / 2 + 0.06, z: M.z - d / 2 + 0.06, w: w - 0.12, d: d - 0.12 } }, [{ species: ids2, density: 4.5, minDistance: 0.32, scale: [0.85, 1.15], prefer: 'any' }], { seed: SEED() + '|' + m.id });
      for (const p of lst) G.pl.push(p); return lst.length > 0;
    }
    const lst = ids.filter(ok); if (!lst.length) return false;
    if (m.type === 'hedge') { const n = Math.max(1, Math.round((M.w || 1) / 0.55)), c = Math.cos(M.ry || 0), sn = Math.sin(M.ry || 0), id = pick(lst); for (let i = 0; i < n; i++) { const lx = -M.w / 2 + (i + 0.5) * M.w / n; G.pl.push({ species: id, x: M.x + lx * c, z: M.z - lx * sn, ry: M.ry || 0, scale: 1, seed: sd + i }); } return true; }
    G.pl.push({ species: pick(lst), x: M.x, z: M.z, ry: M.ry || 0, scale: 1, seed: sd }); return true;
  }
  function assembleVegetation(groups) { // closes the plants collected by vegItem into one merged object per group
    const V = shared.ctx.veg; if (!V) return; let pl = 0, tri = 0; const col = [], lod = [0, 0, 0], mats = V.mats();
    for (const G of V.groups.values()) {
      if (!G.pl.length) continue;
      const lot = V.G.buildLot(G.pl, id => V.S.toSpec(id), Object.assign({ seed: SEED() + '|veg|' + G.group }, V.opts)), obj = V.G.createLotObject(THREE, lot, mats);
      obj.position.y = G.y; obj.name = 'vegetation'; obj.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; o.name = 'veg/' + o.name; o.userData.vegetation = true; } });
      (groups[G.group] || (groups[G.group] = new THREE.Group())).add(obj);
      pl += lot.plantCount - lot.thinnedCount; tri += lot.triangleCount; for (const c of lot.colliders) col.push(Object.assign({ y: G.y, group: G.group }, c)); for (let i = 0; i < 3; i++) lod[i] += lot.lodCounts[i];
    }
    shared.ctx.vegInfo = { plants: pl, triangles: tri, colliders: col, lodCounts: lod, materials: mats };
  }
  Object.assign(K, { VEG_POT, VEG_CACTUS, VEG_MAP, VEG_PLANTER, vegItem, assembleVegetation });
}
